def find_minimum_range(list):
    """Write a function to find the smallest range that includes at-least one element from each of the given arrays.

    Args:
        list: A non-empty collection of non-empty arrays.

    Returns:
        A tuple ``(low, high)`` describing the smallest range that
        contains at least one element from every array. If several
        ranges have the same size, the one with the smallest starting
        value is returned.

    Raises:
        ValueError: If no arrays are given or any array is empty.
    """
    if not list:
        raise ValueError("at least one array is required")

    merged = []
    for list_index, array in enumerate(list):
        if len(array) == 0:
            raise ValueError("each array must contain at least one element")
        for value in array:
            merged.append((value, list_index))

    merged.sort(key=lambda item: item[0])

    counts = [0] * len(list)
    lists_covered = 0
    left = 0
    best_low = None
    best_high = None
    best_size = None

    for right_value, right_list in merged:
        if counts[right_list] == 0:
            lists_covered += 1
        counts[right_list] += 1

        while lists_covered == len(list):
            left_value, left_list = merged[left]
            size = right_value - left_value
            if best_size is None or size < best_size:
                best_size = size
                best_low = left_value
                best_high = right_value

            counts[left_list] -= 1
            if counts[left_list] == 0:
                lists_covered -= 1
            left += 1

    return (best_low, best_high)
